function runAmbientOnce(seed, step) {
  const world = new World({ seed });
  world.step = step | 0;
  const dungeonId = world.create();
  world.add(dungeonId, DungeonState, { worldSeed: seed >>> 0, currentDepth: 3, floorEntityIds: [] });

