/** @type {BumpResolver[]} */
export const BUMP_RESOLVERS = [
  hostileMelee,
  petSwap,
  npcInteract,
  enemyDoorOpen,
  objectInteract,
  pushEntity,
  tileReaction,
];

/**
 * Run bump resolution: iterate resolvers in priority order, execute the first match.
 * @param {any} world
 * @param {number} actor
 * @param {BumpContext} ctx
 * @returns {boolean} true if a resolver handled the bump
 */
export function resolveBump(world, actor, ctx) {
  for (let i = 0; i < BUMP_RESOLVERS.length; i++) {
    const r = BUMP_RESOLVERS[i];
    if (r.test(world, actor, ctx)) {
      r.resolve(world, actor, ctx);
      return true;
    }
  }
  for (let i = 0; i < candidates.length; i++) {
    const r = candidates[i];
    if (bonuses[r.requires.bonus]) return r;
  }
  return null;
}

/**
 * Get all reactions for a tile type (for validation / testing).
 * @param {number} tileType
 * @returns {TileReaction[]}
 */
export function getReactionsForTile(tileType) {
  return _byTile.get(tileType) || [];
}

